import jwt

SSO_PUBLIC_KEY = load_company_sso_public_key()

def validate_sso_token(token):
    try:
        claims = jwt.decode(
            token, SSO_PUBLIC_KEY,
            algorithms=["RS256"], audience="hr-portal-mcp"
        )
    except jwt.ExpiredSignatureError:
        raise PermissionError("SSO token has expired, please sign in again")
    except jwt.InvalidTokenError:
        raise PermissionError("SSO token could not be verified")

    if claims.get("employee_id") is None:
        raise PermissionError("Token is missing an employee identity")

    return claims

@server.call_tool()
async def handle_call_tool(name, arguments, context):
    if name != "get_leave_balance":
        raise ValueError(f"Unknown tool: {name}")

    token = context.get("sso_token")
    claims = validate_sso_token(token)
    employee_id = claims["employee_id"]

    requested_id = arguments.get("employee_id", employee_id)
    if requested_id != employee_id and "hr_admin" not in claims.get("roles", []):
        raise PermissionError("You can only view your own leave balance")

    record = hr_database.fetch_leave_balance(requested_id)
    return [{
        "type": "text",
        "text": f"{record['name']} has {record['days_remaining']} leave days remaining"
    }]

async function answerEmployeeQuestion(question, ssoToken) {
  const [leave, wiki, deploy] = await Promise.all([
    hrClient.callTool("get_leave_balance", {}, { ssoToken }),
    wikiClient.callTool("search_pages", { query: question }, { ssoToken }),
    deployClient.callTool("get_last_deploy", {}, { ssoToken }),
  ]);
  return combineIntoAnswer(question, leave, wiki, deploy);
}
